pgnewstate:
	pgn = int(pgPact[pgstate])
	if pgn <= pgFlag {
		goto pgdefault /* simple state */
	}
	if pgrcvr.char < 0 {
		pgrcvr.char, pgtoken = pglex1(pglex, &pgrcvr.lval)
	}
	pgn += pgtoken
	if pgn < 0 || pgn >= pgLast {
		goto pgdefault
	}
	pgn = int(pgAct[pgn])
	if int(pgChk[pgn]) == pgtoken { /* valid shift */
		pgrcvr.char = -1
		pgtoken = -1
		pgVAL = pgrcvr.lval
		pgstate = pgn
		if Errflag > 0 {
			Errflag--
		}
		goto pgstack
	}

pgdefault:
	/* default state action */
	pgn = int(pgDef[pgstate])
